/**
 * One-human-per-scope enforcement for Self.xyz attestations.
 *
 * A Self `nullifier` is stable per human per scope, so a merchant can use it
 * to bind ONE wallet per verified human per scope: the first wallet to
 * present a valid attestation for a nullifier claims it; any later
 * attestation with the same nullifier + scope but a DIFFERENT wallet is
 * rejected. Same wallet re-presenting is idempotent (allowed).
 *
 * Same pluggable philosophy as NonceStore: a minimal interface with an
 * in-memory default, so a Redis/DB implementation can slot in later.
 */
export interface NullifierRegistry {
    /**
     * Atomically return the wallet bound to (scope, nullifier), binding
     * `wallet` when nothing is bound yet. Resolves to a lowercased address.
     *
     * ASYNC ON PURPOSE, for the same reason as `NonceStore.claim`: the
     * atomicity belongs to the store. A shared implementation needs one
     * conditional write (`INSERT ... ON CONFLICT DO NOTHING RETURNING`), which
     * a synchronous signature cannot express.
     */
    bind(scope: string, nullifier: string, wallet: string): Promise<string>;
}
/**
 * Process-local registry keyed by scope → nullifier → wallet. Unbounded by
 * design (bindings are long-lived identity state, not churn like nonces);
 * deployments that outgrow one process should inject a shared store.
 */
export declare class InMemoryNullifierRegistry implements NullifierRegistry {
    private readonly scopes;
    bind(scope: string, nullifier: string, wallet: string): Promise<string>;
}
